// GetItem 按稳定编号查询事项。
func (svc *Service) GetItem(id string) (Item, error) {
	it, _ := findItem(&svc.store.data, clean(id))
	if it == nil {
		return Item{}, fmt.Errorf("%w：事项 %s", ErrNotFound, id)
	}
	return *it, nil
}

// ItemJourney 凭事项编号汇总它从建立到当前的处理经过：保留事项自身的
// 建立、修改、关闭记录，并加入它参与的各次交接（发起交接、逐轮退回、补充后
// 重新提交、确认接收或继续跟踪），无须先知道涉及哪些交接编号。
// 经过按实际发生时刻排序（带不同时区的时间按同一实际时刻比较）；同一时刻下
// 同一交接内保持发起、该轮退回、该轮重新提交、后续处理的先后，不同交接按
// 交接编号排列。同一次接收若已出现在事项历史里只展示一次。只读查询，
// 不改变事项、交接进度或班次结束时记录。
func (svc *Service) ItemJourney(itemID string) (ItemJourney, error) {
	itemID = clean(itemID)
	d := &svc.store.data
	it, _ := findItem(d, itemID)
	if it == nil {
		return ItemJourney{}, fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
	}
	j := ItemJourney{Item: *it}

	// 排序键：先按实际发生时刻（未记录时间的排最后），同一时刻下事项自身
	// 事件在前，其后按交接编号分组，组内保持生成顺序（发起、逐轮退回、
	// 该轮重新提交、后续处理）。
	type keyedEvent struct {
		ev    JourneyEvent
		group string // "" 表示事项自身事件，否则为交接编号
		ord   int    // 同一（时刻、分组）内的先后
	}
	var events []keyedEvent
	seq := 0
	add := func(ev JourneyEvent, group string) {
		events = append(events, keyedEvent{ev: ev, group: group, ord: seq})
		seq++
	}

	// received 事件与交接中的接收处理是同一次接收，只展示一次（以交接事件
	// 展示，信息更全）；匹配不上的旧数据 received 事件仍原样保留。
	receivedUsed := make([]bool, len(it.Events))

	hs := append([]Handover(nil), d.Handovers...)
	sort.Slice(hs, func(i, k int) bool { return hs[i].ID < hs[k].ID })
	for k := range hs {
		h := &hs[k]
		e, _ := findEntry(h, itemID)
		if e == nil {
			continue
		}
		j.HasHandovers = true
		j.Results = append(j.Results, EntryView{
			HandoverID: h.ID,
			FromShift:  h.FromShiftID,
			ToShift:    h.ToShiftID,
			Entry:      *e,
		})

		// 发起交接：交接记录本身不记操作人，明确显示未记录，不以班次负责人代替。
		add(JourneyEvent{
			At: h.CreatedAt, TimeKnown: !h.CreatedAt.IsZero(),
			Kind: "handover-init", HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
		}, h.ID)
		for _, r := range e.Rounds {
			add(JourneyEvent{
				At: r.ReturnedAt, TimeKnown: !r.ReturnedAt.IsZero(),
				Kind: "return", Operator: r.ReturnOperator,
				HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
				RoundSeq: r.Seq, Reason: r.Reason,
			}, h.ID)
			if r.ResubmittedAt != nil {
				add(JourneyEvent{
					At: *r.ResubmittedAt, TimeKnown: !r.ResubmittedAt.IsZero(),
					Kind: "resubmit", Operator: r.SupplementOperator,
					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
					RoundSeq: r.Seq, Supplement: r.Supplement,
					SupplementOperator: r.SupplementOperator, SupplementAt: r.SupplementAt,
				}, h.ID)
			}
		}
		if e.Status.Received() {
			kind := "confirm"
			if e.Status == EntryTracking {
				kind = "track"
			}
			ev := JourneyEvent{
				Kind: kind, Operator: e.Operator,
				HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
				TrackingNote: e.TrackingNote,
				// 继续跟踪当时指定的后续负责人取自交接记录快照，
				// 之后修改事项负责人不改变这里的历史值。
				FollowOwner: e.FollowOwner,
			}
			if e.ProcessedAt != nil {
				ev.At, ev.TimeKnown = *e.ProcessedAt, true
			}
			add(ev, h.ID)
			if e.ProcessedAt != nil {
				for i := range it.Events {
					iev := &it.Events[i]
					if iev.Kind == "received" && !receivedUsed[i] &&
						iev.At.Equal(*e.ProcessedAt) && iev.Operator == e.Operator {
						receivedUsed[i] = true
						break
					}
				}
			}
		}
	}

	// 事项自身历史：建立、修改、关闭原样保留；未被交接接收事件覆盖的
	// received 事件（旧数据）也保留。
	for i, iev := range it.Events {
		if iev.Kind == "received" && receivedUsed[i] {
			continue
		}
		add(JourneyEvent{
			At: iev.At, TimeKnown: !iev.At.IsZero(),
			Kind: iev.Kind, Operator: iev.Operator, Detail: iev.Detail,
		}, "")
	}

	sort.SliceStable(events, func(i, k int) bool {
		a, b := events[i], events[k]
		if a.ev.TimeKnown != b.ev.TimeKnown {
			return a.ev.TimeKnown
		}
		if a.ev.TimeKnown && !a.ev.At.Equal(b.ev.At) {
			return a.ev.At.Before(b.ev.At)
		}
		if a.group != b.group {
			return a.group < b.group
		}
		return a.ord < b.ord
	})
	for _, ke := range events {
		j.Events = append(j.Events, ke.ev)
	}
	return j, nil
}

// GetHandover 按编号查询交接。
func (svc *Service) GetHandover(id string) (Handover, error) {
	h, _ := findHandover(&svc.store.data, clean(id))
	if h == nil {
		return Handover{}, fmt.Errorf("%w：交接 %s", ErrNotFound, id)
	}
	return *h, nil
}

// ListHandovers 返回全部交接记录，按编号排序。
func (svc *Service) ListHandovers() []Handover {
	out := append([]Handover(nil), svc.store.data.Handovers...)
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// OverlapNotes 返回涉及指定班次的全部重叠说明。
func (svc *Service) OverlapNotes(shiftID string) []OverlapNote {
	shiftID = clean(shiftID)
	out := []OverlapNote{}
	for _, n := range svc.store.data.Notes {
		if n.ShiftA == shiftID || n.ShiftB == shiftID {
			out = append(out, n)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// ShiftReport 按班次汇总完整事项、关闭情况、接班对象、每项交接当前结果与历次退回/补充说明。
// 进行中的班次展示当前事项；已结束班次展示结束时冻结的事项记录，
// 旧数据中缺少结束时记录的班次只展示当前事项并标明历史不完整。
func (svc *Service) ShiftReport(shiftID string) (ShiftReport, error) {
	shiftID = clean(shiftID)
	d := &svc.store.data
	rep := ShiftReport{Results: map[string][]EntryView{}, LatestItems: map[string]Item{}}
	sh, _ := findShift(d, shiftID)
	if sh == nil {
		return ShiftReport{}, fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
	}
	rep.Shift = *sh

	for _, n := range d.Notes {
		if n.ShiftA == sh.ID || n.ShiftB == sh.ID {
			rep.OverlapNotes = append(rep.OverlapNotes, n)
		}
	}
	sort.Slice(rep.OverlapNotes, func(i, j int) bool { return rep.OverlapNotes[i].ID < rep.OverlapNotes[j].ID })

	switch {
	case !sh.Closed:
		// 进行中的班次：事项可继续修改、关闭，展示当前信息。
		rep.Items = currentItemsOfShift(d, sh.ID)
	case sh.CloseRecord != nil:
		// 已结束且有结束时记录：展示冻结的结束时信息，并对照最新状态。
		rep.ItemsAtClose = true
		rep.CloseItems = append([]CloseItemSnapshot(nil), sh.CloseRecord.Items...)
		sort.Slice(rep.CloseItems, func(i, j int) bool { return rep.CloseItems[i].ItemID < rep.CloseItems[j].ItemID })
		for _, s := range rep.CloseItems {
			if it, _ := findItem(d, s.ItemID); it != nil {
				rep.LatestItems[s.ItemID] = *it
			}
		}
	default:
		// 旧数据：结束时未留下记录，只能展示当前信息，不能宣称是结束时事实。
		rep.HistoryIncomplete = true
		rep.Items = currentItemsOfShift(d, sh.ID)
	}
	sort.Slice(rep.Items, func(i, j int) bool { return rep.Items[i].ID < rep.Items[j].ID })

	for i := range d.Handovers {
		h := &d.Handovers[i]
		involved := h.FromShiftID == sh.ID || h.ToShiftID == sh.ID
		if !involved {
			continue
		}
		if h.FromShiftID == sh.ID {
			cp := *h
			rep.Outgoing = &cp
		}
		if h.ToShiftID == sh.ID {
			rep.Incoming = append(rep.Incoming, *h)
		}
		for j := range h.Entries {
			rep.Results[h.Entries[j].ItemID] = append(rep.Results[h.Entries[j].ItemID], EntryView{
				HandoverID: h.ID,
				FromShift:  h.FromShiftID,
				ToShift:    h.ToShiftID,
				Entry:      h.Entries[j],
			})
		}
	}
	sort.Slice(rep.Incoming, func(i, j int) bool { return rep.Incoming[i].ID < rep.Incoming[j].ID })
	for k := range rep.Results {
		sort.Slice(rep.Results[k], func(i, j int) bool { return rep.Results[k][i].HandoverID < rep.Results[k][j].HandoverID })
	}
	return rep, nil
}

package handover

import (
	"errors"
	"strings"
	"time"
)

// Severity 是事项的严重程度。
type Severity string

const (
	SeverityNormal    Severity = "normal"    // 普通
	SeverityImportant Severity = "important" // 重要
	SeverityUrgent    Severity = "urgent"    // 紧急
)

// ParseSeverity 解析严重程度，接受英文标识与中文名称；空串非法。
func ParseSeverity(s string) (Severity, error) {
	switch strings.ToLower(strings.TrimSpace(s)) {
	case "normal", "普通":
		return SeverityNormal, nil
	case "important", "重要":
		return SeverityImportant, nil
	case "urgent", "紧急":
		return SeverityUrgent, nil
	}
	return "", errors.New("严重程度无效：必须是 normal(普通)、important(重要)、urgent(紧急) 之一")
}

func (v Severity) valid() bool {
	return v == SeverityNormal || v == SeverityImportant || v == SeverityUrgent
}

// Label 返回严重程度的中文展示名。
func (v Severity) Label() string {
	switch v {
	case SeverityNormal:
		return "普通"
	case SeverityImportant:
		return "重要"
	case SeverityUrgent:
		return "紧急"
	}
	return string(v)
}

// EntryStatus 是交接事项的当前处理结果。
type EntryStatus string

const (
	EntryPending   EntryStatus = "pending"   // 待处理
	EntryConfirmed EntryStatus = "confirmed" // 确认接收
	EntryTracking  EntryStatus = "tracking"  // 继续跟踪（已接收）
	EntryReturned  EntryStatus = "returned"  // 退回
)

// Label 返回交接结果的中文展示名。
func (s EntryStatus) Label() string {
	switch s {
	case EntryPending:
		return "待处理"
	case EntryConfirmed:
		return "确认接收"
	case EntryTracking:
		return "继续跟踪"
	case EntryReturned:
		return "退回"
	}
	return string(s)
}

// Received 报告该结果是否表示接班班次已经接收。
func (s EntryStatus) Received() bool {
	return s == EntryConfirmed || s == EntryTracking
}

// EntryAction 是接班人对单项交接事项可执行的操作。
type EntryAction string

const (
	ActionConfirm EntryAction = "confirm" // 确认接收
	ActionReturn  EntryAction = "return"  // 退回
	ActionTrack   EntryAction = "track"   // 继续跟踪
)

// ParseAction 解析交接操作，接受英文标识与中文名称。
func ParseAction(s string) (EntryAction, error) {
	switch strings.ToLower(strings.TrimSpace(s)) {
	case "confirm", "确认", "确认接收":
		return ActionConfirm, nil
	case "return", "退回":
		return ActionReturn, nil
	case "track", "tracking", "继续跟踪", "跟踪":
		return ActionTrack, nil
	}
	return "", errors.New("操作无效：必须是 confirm(确认接收)、return(退回)、track(继续跟踪) 之一")
}

// Shift 是一个岗位班次，编号全局稳定。
type Shift struct {
	ID        string     `json:"id"`
	Position  string     `json:"position"`
	Owner     string     `json:"owner"`
	Start     time.Time  `json:"start"`
	End       time.Time  `json:"end"`
	CreatedAt time.Time  `json:"created_at"`
	Closed    bool       `json:"closed"`
	ClosedAt  *time.Time `json:"closed_at,omitempty"`
	// CloseRecord 是班次成功结束时留下的事项记录，一经写定不再随事项的后续
	// 修改、关闭或流转而改变。nil 表示该班次结束时未留下记录（旧数据）。
	CloseRecord *ShiftCloseRecord `json:"close_record,omitempty"`
}

// CloseItemSnapshot 冻结班次结束时刻某一事项的内容、严重程度、限制条件、
// 后续负责人与关闭情况。结束前已关闭的事项保留关闭人与关闭时间；
// 结束时未关闭的事项，之后无论由哪一班关闭，都不改变这里的未关闭记录。
type CloseItemSnapshot struct {
	ItemID        string     `json:"item_id"`
	Content       string     `json:"content"`
	Severity      Severity   `json:"severity"`
	Constraints   string     `json:"constraints,omitempty"`
	FollowOwner   string     `json:"follow_owner"`
	Closed        bool       `json:"closed"`
	ClosedAt      *time.Time `json:"closed_at,omitempty"`
	CloseOperator string     `json:"close_operator,omitempty"`
}

// ShiftCloseRecord 是班次成功结束时在班全部事项的冻结清单。
// Items 包含该班新增与已经接收的事项，也保留结束前已关闭的事项；
// 尚未确认或被退回的交接事项不在其中（仍留在交接记录里）。
// 空切片表示结束时没有事项，与缺少历史记录（CloseRecord 为 nil）相区别。
type ShiftCloseRecord struct {
	Items []CloseItemSnapshot `json:"items"`
}

// ItemEvent 是事项的追加式历史事件。
type ItemEvent struct {
	At       time.Time `json:"at"`
	Kind     string    `json:"kind"`
	Operator string    `json:"operator,omitempty"`
	Detail   string    `json:"detail,omitempty"`
}

// Item 是一项未关闭事项。编号全局稳定，跨班次交接保持不变。
type Item struct {
	ID             string      `json:"id"`
	OriginShiftID  string      `json:"origin_shift_id"`
	ShiftIDs       []string    `json:"shift_ids"`
	CurrentShiftID string      `json:"current_shift_id"`
	Content        string      `json:"content"`
	Severity       Severity    `json:"severity"`
	Constraints    string      `json:"constraints,omitempty"`
	FollowOwner    string      `json:"follow_owner"`
	CreatedAt      time.Time   `json:"created_at"`
	Closed         bool        `json:"closed"`
	ClosedAt       *time.Time  `json:"closed_at,omitempty"`
	CloseOperator  string      `json:"close_operator,omitempty"`
	Events         []ItemEvent `json:"events"`
}

// ReturnRound 记录一次退回以及交班人随后的补充说明与重新提交。
// 原文与退回原因一经写入不再覆盖。
type ReturnRound struct {
	Seq                int        `json:"seq"`
	ReturnedAt         time.Time  `json:"returned_at"`
	ReturnOperator     string     `json:"return_operator"`
	Reason             string     `json:"reason"`
	Supplement         string     `json:"supplement,omitempty"`
	SupplementOperator string     `json:"supplement_operator,omitempty"`
	SupplementAt       *time.Time `json:"supplement_at,omitempty"`
	ResubmittedAt      *time.Time `json:"resubmitted_at,omitempty"`
}

// HandoverEntry 是交接清单中的单项处理记录。
type HandoverEntry struct {
	ItemID       string        `json:"item_id"`
	Content      string        `json:"content"`
	Severity     Severity      `json:"severity"`
	Constraints  string        `json:"constraints,omitempty"`
	FollowOwner  string        `json:"follow_owner"`
	Status       EntryStatus   `json:"status"`
	Operator     string        `json:"operator,omitempty"`
	ProcessedAt  *time.Time    `json:"processed_at,omitempty"`
	TrackingNote string        `json:"tracking_note,omitempty"`
	Rounds       []ReturnRound `json:"rounds,omitempty"`
}

// Handover 是一个交班班次对接班班次发起的一次交接。
type Handover struct {
	ID          string          `json:"id"`
	Position    string          `json:"position"`
	FromShiftID string          `json:"from_shift_id"`
	ToShiftID   string          `json:"to_shift_id"`
	CreatedAt   time.Time       `json:"created_at"`
	CompletedAt *time.Time      `json:"completed_at,omitempty"`
	Entries     []HandoverEntry `json:"entries"`
}

// Completed 报告交接是否已完成。
func (h *Handover) Completed() bool {
	for i := range h.Entries {
		st := h.Entries[i].Status
		if st == EntryPending || st == EntryReturned {
			return false
		}
	}
	return true
}

// OverlapNote 记录同一岗位两个重叠班次的重叠说明。
type OverlapNote struct {
	ID        string    `json:"id"`
	Position  string    `json:"position"`
	ShiftA    string    `json:"shift_a"`
	ShiftB    string    `json:"shift_b"`
	Note      string    `json:"note"`
	CreatedAt time.Time `json:"created_at"`
}

// JourneyEvent 是事项处理经过中的一条记录：可能来自事项自身历史
// （建立/修改/关闭/接收），也可能来自它参与的交接（发起交接、逐轮退回、
// 补充后重新提交、确认接收、继续跟踪）。交接相关事件带有交接编号与交班、
// 接班班次；Operator 为空表示该操作人未记录（旧数据可能缺人名）。
type JourneyEvent struct {
	At                 time.Time  // 实际发生时刻；TimeKnown 为 false 表示未记录
	TimeKnown          bool       // At 是否有效（旧数据可能缺时间）
	Kind               string     // created/updated/closed/received/handover-init/return/resubmit/confirm/track
	Operator           string     // 实际操作人；空表示未记录
	Detail             string     // 事项自身事件附带的说明
	HandoverID         string     // 交接相关事件所属的交接编号
	FromShift          string     // 交班班次
	ToShift            string     // 接班班次
	RoundSeq           int        // 退回/重新提交的轮次
	Reason             string     // 该轮完整退回原因
	Supplement         string     // 该轮补充说明
	SupplementOperator string     // 补充人
	SupplementAt       *time.Time // 补充时间
	TrackingNote       string     // 继续跟踪的跟踪说明
	FollowOwner        string     // 继续跟踪当时指定的后续负责人（不随后续修改改变）
}

// ItemJourney 是凭事项编号查询得到的完整处理经过：开头为事项最新状态，
// Events 是合并事项自身历史与各次交接经过后的时间线，Results 是该事项在
// 每次交接中的当前处理结果。
type ItemJourney struct {
	Item         Item
	Events       []JourneyEvent // 按实际发生时刻排序（不同时区按同一实际时刻比较）
	Results      []EntryView    // 按交接编号排列
	HasHandovers bool           // false 表示尚未参与交接
}

// EntryView 把交接单项与其所属交接编号关联，用于按班次查询。
type EntryView struct {
	HandoverID string
	FromShift  string
	ToShift    string
	Entry      HandoverEntry
}

// ShiftReport 是按班次查询得到的完整视图。
type ShiftReport struct {
	Shift        Shift
	OverlapNotes []OverlapNote
	// Items 是进行中班次的当前事项，或旧数据班次（无结束时记录）的当前事项。
	Items []Item
	// CloseItems 是已结束班次结束时刻的事项快照（已冻结），按事项编号排列。
	CloseItems []CloseItemSnapshot
	// ItemsAtClose 为 true 表示本次查到了结束时记录，CloseItems 即结束时事实。
	ItemsAtClose bool
	// HistoryIncomplete 为 true 表示该已结束班次是旧数据、缺少结束时记录，
	// Items 只是当前信息，不能视为结束时事实。
	HistoryIncomplete bool
	// LatestItems 按事项编号索引结束时事项的最新状态，与结束时信息对照。
	LatestItems map[string]Item
	Outgoing    *Handover
	Incoming    []Handover
	// Results 按事项编号汇总它在历次交接中的当前结果与退回历史。
	Results map[string][]EntryView
}

// Command handover 是本地班次交接与未关闭事项的命令行入口。
//
// 数据默认保存在当前目录 handover-data.json，可用全局参数 --data 或环境变量
// HANDOVER_DATA 指定。时间统一使用带时区偏移的 RFC3339，如
// 2026-10-02T08:00:00+08:00。
package main

import (
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"time"

	"github.com/bengzyyys/shift-handover/handover"
)

func main() {
	os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
}

const usageText = `用法：handover [--data 文件] <命令> [参数]

数据持久化在本地 JSON 文件中，退出后重新打开数据仍在。
时间使用带时区的 RFC3339，例如 2026-10-02T08:00:00+08:00。

班次：
  shift-add      建立班次        --position 岗位 --owner 负责人 --start 开始 --end 结束
                                 [--note 重叠说明（与同岗位已存班次区间重叠时必填）]
  shift-list     列出全部班次
  shift-close    结束班次        --id 班次编号
  shift-show     按班次查询      --id 班次编号（完整事项/交接/结果）

重叠说明：
  note-add       为重叠班次填说明 --a 班次 --b 班次 --note 说明
  note-list      查看班次涉及的重叠说明 --id 班次

事项：
  item-add       新增事项        --shift 班次 --content 内容 \
                                 --severity normal|important|urgent \
                                 [--constraints 限制条件] --follow 后续负责人
  item-update    修改事项        --id 事项编号 --content 内容 \
                                 --severity normal|important|urgent \
                                 [--constraints 限制条件] --follow 后续负责人
  item-close     关闭事项        --id 事项编号 --operator 操作人
  item-show      查询事项        --id 事项编号（最新状态、完整处理经过与各次交接当前结果）

交接：
  handover-create   发起交接      --from 交班班次 --to 接班班次
  handover-list     列出全部交接
  handover-show     查看交接      --id 交接编号
  handover-process  接班人处理单项 --id 交接编号 --item 事项编号 \
                                 --action confirm|return|track --operator 操作人 \
                                 [--reason 退回原因] [--note 跟踪说明] [--follow 后续负责人]
  handover-resubmit 交班人补充并重新提交退回项 \
                                 --id 交接编号 --item 事项编号 \
                                 --operator 操作人 --supplement 补充说明
`

func run(argv []string, stdout, stderr io.Writer) int {
	args := append([]string(nil), argv...)
	dataPath := os.Getenv("HANDOVER_DATA")
	// 抽出全局 --data。
	rest := make([]string, 0, len(args))
	for i := 0; i < len(args); i++ {
		switch {
		case args[i] == "--data" && i+1 < len(args):
			dataPath = args[i+1]
			i++
		case len(args[i]) > 7 && args[i][:7] == "--data=":
			dataPath = args[i][7:]
		default:
			rest = append(rest, args[i])
		}
	}
	if dataPath == "" {
		dataPath = "handover-data.json"
	}

	if len(rest) == 0 || rest[0] == "-h" || rest[0] == "--help" || rest[0] == "help" {
		fmt.Fprint(stdout, usageText)
		return 0
	}

	cmd, cmdArgs := rest[0], rest[1:]
	store, err := handover.Open(dataPath)
	if err != nil {
		fmt.Fprintf(stderr, "错误：%v\n", err)
		return 1
	}
	svc := handover.NewService(store)

	out, err := dispatch(svc, cmd, cmdArgs)
	if err != nil {
		fmt.Fprintf(stderr, "错误：%v\n", err)
		return 1
	}
	if out != "" {
		fmt.Fprint(stdout, out)
		if len(out) > 0 && out[len(out)-1] != '\n' {
			fmt.Fprintln(stdout)
		}
	}
	return 0
}

func dispatch(svc *handover.Service, cmd string, args []string) (string, error) {
	fs := flag.NewFlagSet(cmd, flag.ContinueOnError)
	fs.SetOutput(io.Discard)

	var (
		id, position, owner, startS, endS              string
		a, b                                           string
		shift, content, severityS, constraints, follow string
		operator, from, to                             string
		item, actionS, reason, note, supplement        string
	)
	fs.StringVar(&id, "id", "", "记录编号")
	fs.StringVar(&position, "position", "", "岗位")
	fs.StringVar(&owner, "owner", "", "负责人")
	fs.StringVar(&startS, "start", "", "开始时间 RFC3339")
	fs.StringVar(&endS, "end", "", "结束时间 RFC3339")
	fs.StringVar(&a, "a", "", "班次编号 A")
	fs.StringVar(&b, "b", "", "班次编号 B")
	// note-add 时为重叠说明；handover-process --action track 时为跟踪说明。
	fs.StringVar(&note, "note", "", "重叠说明 / 跟踪说明")
	fs.StringVar(&shift, "shift", "", "班次编号")
	fs.StringVar(&content, "content", "", "事项内容")
	fs.StringVar(&severityS, "severity", "", "严重程度 normal|important|urgent")
	fs.StringVar(&constraints, "constraints", "", "限制条件（可空）")
	// follow 同时用于后续负责人（新增/修改事项）与跟踪后续负责人（track）。
	fs.StringVar(&follow, "follow", "", "后续负责人")
	fs.StringVar(&operator, "operator", "", "操作人")
	fs.StringVar(&from, "from", "", "交班班次编号")
	fs.StringVar(&to, "to", "", "接班班次编号")
	fs.StringVar(&item, "item", "", "事项编号")
	fs.StringVar(&actionS, "action", "", "confirm|return|track")
	fs.StringVar(&reason, "reason", "", "退回原因")
	fs.StringVar(&supplement, "supplement", "", "补充说明")
	if err := fs.Parse(args); err != nil {
		return "", err
	}

	switch cmd {
	case "shift-add":
		start, err := parseTime("--start", startS)
		if err != nil {
			return "", err
		}
		end, err := parseTime("--end", endS)
		if err != nil {
			return "", err
		}
		sh, err := svc.CreateShift(position, owner, start, end, note)
		if err != nil {
			return "", err
		}
		return "已建立班次 " + handover.FormatShift(sh), nil

	case "shift-list":
		shifts := svc.ListShifts()
		if len(shifts) == 0 {
			return "（暂无班次）", nil
		}
		out := ""
		for _, sh := range shifts {
			out += handover.FormatShift(sh) + "\n"
		}
		return out, nil

	case "shift-close":
		sh, err := svc.CloseShift(id)
		if err != nil {
			return "", err
		}
		return "已结束班次 " + handover.FormatShift(sh), nil

	case "shift-show":
		rep, err := svc.ShiftReport(id)
		if err != nil {
			return "", err
		}
		return handover.FormatReport(rep), nil

	case "note-add":
		n, err := svc.AddOverlapNote(a, b, note)
		if err != nil {
			return "", err
		}
		return "已保存重叠说明 " + handover.FormatOverlapNote(n), nil

	case "note-list":
		notes := svc.OverlapNotes(id)
		if len(notes) == 0 {
			return "（无重叠说明）", nil
		}
		out := ""
		for _, n := range notes {
			out += handover.FormatOverlapNote(n) + "\n\n"
		}
		return out, nil

	case "item-add":
		sev, err := handover.ParseSeverity(severityS)
		if err != nil {
			return "", err
		}
		it, err := svc.AddItem(shift, content, sev, constraints, follow)
		if err != nil {
			return "", err
		}
		return "已新增事项\n" + handover.FormatItem(it), nil

	case "item-update":
		sev, err := handover.ParseSeverity(severityS)
		if err != nil {
			return "", err
		}
		it, err := svc.UpdateItem(id, content, sev, constraints, follow)
		if err != nil {
			return "", err
		}
		return "已修改事项\n" + handover.FormatItem(it), nil

	case "item-close":
		it, err := svc.CloseItem(id, operator)
		if err != nil {
			return "", err
		}
		return "已关闭事项\n" + handover.FormatItem(it), nil

	case "item-show":
		j, err := svc.ItemJourney(id)
		if err != nil {
			return "", err
		}
		return handover.FormatItemJourney(j), nil

	case "handover-create":
		h, err := svc.CreateHandover(from, to)
		if err != nil {
			if errors.Is(err, handover.ErrHandoverExists) {
				// 重复发起返回已有记录，不视为失败。
				return "已存在交接记录（重复发起，返回已有记录）\n" + handover.FormatHandover(h), nil
			}
			return "", err
		}
		return "已发起交接\n" + handover.FormatHandover(h), nil

	case "handover-list":
		hs := svc.ListHandovers()
		if len(hs) == 0 {
			return "（暂无交接记录）", nil
		}
		out := ""
		for _, h := range hs {
			out += handover.FormatHandover(h) + "\n"
		}
		return out, nil

	case "handover-show":
		h, err := svc.GetHandover(id)
		if err != nil {
			return "", err
		}
		return handover.FormatHandover(h), nil

	case "handover-process":
		action, err := handover.ParseAction(actionS)
		if err != nil {
			return "", err
		}
		h, err := svc.ProcessEntry(id, item, action, operator, reason, note, follow)
		if err != nil {
			return "", err
		}
		return "已处理\n" + handover.FormatHandover(h), nil

	case "handover-resubmit":
		h, err := svc.ResubmitReturned(id, item, operator, supplement)
		if err != nil {
			return "", err
		}
		return "已补充说明并重新提交\n" + handover.FormatHandover(h), nil

	default:
		return "", fmt.Errorf("未知命令 %q，运行 handover help 查看用法", cmd)
	}
}

func parseTime(name, s string) (time.Time, error) {
	if s == "" {
		return time.Time{}, fmt.Errorf("%s 不能为空，格式为带时区的 RFC3339（如 2026-10-02T08:00:00+08:00）", name)
	}
	t, err := time.Parse(time.RFC3339, s)
	if err != nil {
		return time.Time{}, fmt.Errorf("%s 时间格式无效：%w（应为 RFC3339，如 2026-10-02T08:00:00+08:00）", name, err)
	}
	return t, nil
}

